css:
#tongsci1-3-2-2-3-design .head.split .ds-ask { font-size: 38px; white-space: normal; max-width: 620px; text-align: right; line-height: 1.15; margin: 0; }
#tongsci1-3-2-2-3-design .ds-body { grid-template-columns: 1040px minmax(0, 1fr); }
.ds-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #dfeaf2; }
.ds-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
.ds-stage canvas.holding { cursor: grabbing; }
.ds-stage .now-chip { top: 132px; }
.ds-panel { gap: 12px; }
.ds-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; flex: none; }
.ds-out b { color: var(--accent); }
.ds-eval { width: 100%; border-collapse: collapse; table-layout: fixed; flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
.ds-eval thead th { font: 700 18px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; }
.ds-eval tbody th { font: 800 18px/1.25 var(--f-body); color: var(--accent); border: 1.5px solid var(--rule, #c9ccd3); padding: 4px 6px; text-align: center; }
.ds-eval td { border: 1.5px solid var(--rule, #c9ccd3); padding: 4px 8px; font: 500 18px/1.3 var(--f-body); }
.ds-eval td.st { text-align: center; font: 800 22px/1 var(--f-body); color: #e0a400; letter-spacing: 1px; white-space: nowrap; }
.ds-eval td.st small { display: block; font: 600 14px/1.2 var(--f-body); color: var(--ink-3); letter-spacing: 0; margin-top: 2px; white-space: normal; }
.ds-eval tr.pop td.st { animation: u-pop .5s ease; }
.ds-cons { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; flex: none; }
.ds-cons li { display: flex; align-items: center; gap: 8px; font: 500 19px/1.3 var(--f-body); color: var(--ink-3); padding: 4px 10px; border: 2px dashed var(--ink-3); border-radius: 10px; }
.ds-cons li > span { font-weight: 800; color: inherit; min-width: 4.6em; }
.ds-cons li i { font-style: normal; font-weight: 700; padding: 1px 10px; border-radius: 999px; border: 1.5px solid currentColor; }
.ds-cons li i.on { background: var(--hl); color: var(--ink); border-color: var(--ink); }
.ds-cons li.on { color: var(--ink); border-style: solid; border-color: var(--good); background: var(--good-soft); }
.ds-cons li.on > span::before { content: "★ "; color: #e0a400; }
section.ex.u-done .ds-cons { display: none; }

